/* PROTOTYPE: fictional data, no backend or persistent storage. Question: which mobile layout makes weekly signup and on-court administration easiest? */
const paths = {
  ball:'<circle cx="12" cy="12" r="9"/><path d="M7 4.5c4 2 5 5 5 7.5m8.5-3.5c-4-1-7 .5-8.5 3.5m-1 9c2.5-3 3-6 .8-9M4 8c2 4 5 5 8 4m6 6c-1-4-3-5.5-6-6"/>',
  home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',
  trophy:'<path d="M8 3h8v6a4 4 0 0 1-8 0V3ZM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v6m-4 2h8m-6-2h4"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  pin:'<path d="M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  right:'<path d="m9 5 7 7-7 7"/>',
  left:'<path d="m15 5-7 7 7 7"/>',
  arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
  swap:'<path d="M4 8h16m-5-4 5 4-5 4M20 16H4m5-4-5 4 5 4"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',
  leaf:'<path d="M4 20c0-9 7-15 16-16 0 10-4 16-11 16-3 0-5-2-5-5m0 5L15 9"/>',
  people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',
  lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3m-4 4v3"/>',
  print:'<path d="M7 8V3h10v5M7 17H3V8h18v9h-4M7 14h10v7H7Z"/><path d="M17 11h1"/>',
  close:'<path d="m6 6 12 12M18 6 6 18"/>',
  shuffle:'<path d="M3 5h3c5 0 7 14 12 14h3m-4-4 4 4-4 3M3 19h3c2 0 4-4 6-7m2-4c1-2 3-3 4-3h3m-4-3 4 3-4 4"/>',
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.ball}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const people=[
  ['Arkadiusz Dalecki',1128,true],['Michał Nowak',1216,true],['Kamil Wiśniewski',1184,true],['Piotr Zieliński',1160,true],['Tomasz Wójcik',1096,true],['Anna Kamińska',1082,true],['Mateusz Lewandowski',1064,false],['Katarzyna Dąbrowska',1052,false],['Paweł Szymański',1040,false],['Julia Woźniak',1028,false],['Jakub Kozłowski',1016,false],['Marta Jankowska',1004,false],['Marcin Mazur',992,false],['Aleksandra Krawczyk',980,false],['Filip Kaczmarek',1000,false],['Natalia Piotrowska',1000,false]
].map(([name,elo,founder],id)=>({id,name,elo,nickname:'',priorityStatus:founder?'founder':id>=14?'guest':'player'}));
const priorityLabel = player => ({founder:'Założyciel',player:'Zawodnik',guest:'Gość'})[player.priorityStatus];
const initialEvent=(date)=>({date,roster:date==='2026-11-10'?Array.from({length:14},(_,i)=>i):[1,2,3,4,5,6,7,8],wait:date==='2026-11-10'?[14,15]:[],mine:date==='2026-11-10'?'confirmed':'none',cancelled:date==='2026-11-24',changed:false,offer:false,attending:Array.from({length:12},(_,i)=>i),step:0,teams:null,locked:false,score:null,scoreDraft:[0,0]});
const events=new Map();
const focusedPrototype = new URLSearchParams(location.search).get('focused') === '1';
if (focusedPrototype) document.documentElement.classList.add('focused-prototype');
const state={page:'meeting',admin:false,date:'2026-11-10',month:10,year:2026,rankingTab:'players',variant:['A','B','C'].includes(new URLSearchParams(location.search).get('variant'))?new URLSearchParams(location.search).get('variant'):'A'};
const getEvent=()=>{if(!events.has(state.date))events.set(state.date,initialEvent(state.date));return events.get(state.date)};
const dateObj=date=>new Date(date+'T12:00:00');
const longDate=date=>dateObj(date).toLocaleDateString('pl-PL',{day:'numeric',month:'long'});
const weekday=date=>dateObj(date).toLocaleDateString('pl-PL',{weekday:'long'});
const initials=p=>p.name.split(' ').map(s=>s[0]).slice(0,2).join('');
const avatar=(id,extra='')=>`<span class="avatar ${id===0?'me':''} ${extra}" style="${id!==0?`background:${['#eaf0e4','#eceae1','#e9eee9','#f3eadd','#e8eeed','#eee9e4'][id%6]}`:''}">${initials(people[id])}</span>`;
const brand=()=>`<div class="brand">${icon('ball')}volleycrew<span class="brand-dot">.</span></div>`;
const nav=()=>`<nav class="nav" aria-label="Menu główne">${[['meeting','home','Spotkanie'],['calendar','calendar','Kalendarz'],['ranking','trophy','Ranking'],['profile','user','Mój profil']].map(([key,i,label])=>`<button data-page="${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}>${icon(i)}${label}${key==='meeting'?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav>`;
const mobileNav=()=>`<nav class="mobile-nav" aria-label="Menu na telefonie">${[['meeting','home','Spotkanie'],['calendar','calendar','Kalendarz'],['ranking','trophy','Ranking'],['profile','user','Profil']].map(([key,i,label])=>`<button data-page="${key}" class="${state.page===key?'active':''}" ${state.page===key?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav>`;
const roleButton=()=>`<button class="role-toggle ${state.admin?'on':''}" data-action="role" aria-pressed="${state.admin}">${icon('shield')}${state.admin?'Organizator':'Widok zawodnika'}</button>`;
const demoBadge=()=>`<button class="demo-badge" data-action="scenarios" title="Zmień przykładowy stan spotkania">Dane demo</button>`;
const topActions=()=>`<div class="top-actions">${demoBadge()}${roleButton()}${avatar(0)}</div>`;
const sidebar=()=>`<aside class="sidebar">${brand()}<p class="group-label">TWOJA EKIPA</p>${nav()}<div class="sidebar-bottom"><div class="venue-note">${icon('pin')}<p><strong>Wtorki należą do nas.</strong><br>I LO w Gdańsku<br>18:00 — 20:00</p></div><div class="person">${avatar(0)}<div><div class="person-name">${esc(people[0].name)}</div><div class="person-sub">${state.admin?'Administrator':priorityLabel(people[0])}</div></div></div></div></aside>`;
const topbar=()=>`<header class="topbar">${brand()}<div class="breadcrumb">Twoja ekipa ${icon('right')} <strong>${({meeting:'Najbliższe spotkanie',calendar:'Kalendarz',ranking:'Ranking',profile:'Mój profil'})[state.page]}</strong></div>${topActions()}</header>`;
const pageHead=(title,subtitle)=>`<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="date-today">${icon('calendar')} Czwartek, 5 listopada 2026</div></div>`;
const court=()=>`<div class="court-art" aria-hidden="true"><span class="hero-rail">MEET · PLAY · REPEAT</span><svg viewBox="0 0 330 300" fill="none"><circle cx="210" cy="160" r="123" fill="#295847"/><circle cx="210" cy="160" r="98" stroke="#3e6b52" stroke-dasharray="3 7"/><g transform="translate(53 117) rotate(-24 112 70)"><rect x="10" y="8" width="210" height="139" rx="3" fill="#739263"/><rect x="23" y="20" width="184" height="114" stroke="#d8e6b4" stroke-width="1.5"/><path d="M115 20v114M73 20v114m84-114v114" stroke="#d8e6b4" stroke-width="1.2"/><path d="M115 0v148" stroke="#eff4dc" stroke-width="2"/><path d="M115 0h8v147h-8" fill="#cbdca7" fill-opacity=".2"/></g><ellipse cx="208" cy="221" rx="43" ry="9" fill="#173c31" fill-opacity=".3"/><g transform="translate(175 125) rotate(15 36 36)"><circle cx="36" cy="36" r="43" fill="#e8eda8"/><path d="M9 3c21 9 30 20 30 35M75 16c-18-2-30 6-36 22m-9 40c14-13 19-24 9-40M-3 23c12 15 25 19 42 15m25 28c-5-18-13-26-25-28" stroke="#446144" stroke-width="2.2"/><path d="M3 17c11 15 21 19 36 21m29-33c-17 0-25 9-29 18m7 51c7-17 7-27-7-36" stroke="#446144" stroke-width="1.2"/><circle cx="36" cy="36" r="43" stroke="#c4d58f"/></g><circle cx="119" cy="64" r="4" fill="#b5cf8a"/><path d="m263 85 4 6m-12-1 5-2" stroke="#b5cf8a" stroke-width="2" stroke-linecap="round"/></svg></div>`;
function hero(){const e=getEvent();return `<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span>${e.cancelled?'SPOTKANIE ODWOŁANE':e.changed?'NOWY TERMIN · POTWIERDŹ UDZIAŁ':'KOLEJNY DOBRY WIECZÓR'}</div><h2>${longDate(e.date)}</h2><div class="hero-detail">${icon('clock')} ${weekday(e.date)}, 18:00 — 20:00</div><div class="hero-detail">${icon('pin')} I LO w Gdańsku</div><div class="hero-bottom">${icon('people')} ${e.cancelled?'Widzimy się na kolejnym spotkaniu':`${e.roster.length} z 14 miejsc zajętych · 2 godziny gry`}</div></div>${court()}</section>`}
function rsvp(){const e=getEvent();if(e.cancelled)return `<div class="rsvp"><div><div class="rsvp-title">Spotkanie odwołane</div><p>Ten termin pozostaje w historii. Nie naliczamy nieobecności.</p></div><button class="button" data-page="calendar">Inne terminy ${icon('arrow')}</button></div>`;
  const status=e.offer?['Mamy dla Ciebie wolne miejsce','Potwierdź, zanim organizator zaproponuje je kolejnej osobie.']:e.changed?['Termin spotkania się zmienił','Sprawdź nową datę i ponownie potwierdź, czy zagrasz.']:({confirmed:['Jesteś w grze!','Masz potwierdzone miejsce. Do zobaczenia na boisku.'],wait:['Jesteś na liście rezerwowej',`Twoja pozycja: ${e.wait.indexOf(0)+1}. Organizator powiadomi Cię o wolnym miejscu.`],absent:['Tym razem bez Ciebie','Możesz zmienić deklarację, jeśli Twoje plany się zmienią.'],none:['Grasz z nami?','Daj znać ekipie, czy wpadasz na najbliższe spotkanie.']})[e.mine];
  const buttons=e.offer?`<button class="button primary" data-action="accept-offer">Przyjmuję miejsce ${icon('check')}</button><button class="button" data-action="decline-offer">Nie mogę</button>`:e.changed||e.mine==='none'||e.mine==='absent'?`<button class="button primary" data-action="join">${e.changed?'Potwierdzam udział':e.roster.length<14?'Będę na miejscu':'Zapisz mnie do rezerwy'} ${icon('arrow')}</button>${e.mine!=='absent'?'<button class="button" data-action="absent">Nie będę</button>':''}`:`<button class="button small" data-action="withdraw">${e.mine==='wait'?'Wycofaj zgłoszenie':'Zmień deklarację'}</button>`;
  return `<div class="rsvp"><div><div class="rsvp-title"><span class="status-check">${icon(e.mine==='confirmed'?'check':e.mine==='wait'?'clock':'calendar')}</span>${status[0]}</div><p>${status[1]}</p></div><div class="rsvp-actions">${buttons}</div></div><div class="capacity"><div class="capacity-label"><span>Lista uczestników</span><strong>${e.roster.length}/14 · ${e.roster.length<14?`${14-e.roster.length} wolne miejsca`:'komplet ekipy'}</strong></div><div class="progress"><span style="width:${e.roster.length/14*100}%"></span></div></div>`}
function roster(){const e=getEvent();return `<section class="card roster"><div class="card-heading"><h2>Widzimy się na boisku <span class="count-pill">${e.roster.length}</span></h2><button class="text-button" data-action="signup-info">Zasady zapisów ${icon('right')}</button></div><div class="roster-grid">${e.roster.map((id,n)=>`<div class="player-row"><span class="row-number">${String(n+1).padStart(2,'0')}</span>${avatar(id)}<div class="player-meta"><div class="player-name">${esc(people[id].name)}${id===0?'<span class="you">Ty</span>':''}</div>${state.admin?`<div class="founder">${priorityLabel(people[id])}</div>`:''}</div>${icon('check','check-tiny')}</div>`).join('')}</div><div class="waitlist"><div class="waitlist-title">Lista rezerwowa <span class="count-pill">${e.wait.length}</span></div>${e.wait.length?`<p>Wolne miejsce wymaga potwierdzenia. Damy znać na Messengerze.</p>${e.wait.map((id,n)=>`<div class="wait-player"><span class="row-number">${n+1}</span>${avatar(id)}${esc(people[id].name)}${id===0?'<span class="you">Ty</span>':''}</div>`).join('')}`:'<p class="empty-wait">Na razie nikt nie czeka na miejsce.</p>'}</div></section>`}
function personalCard(){const rank=[...people].sort((a,b)=>b.elo-a.elo).findIndex(p=>p.id===0)+1;return `<section class="card profile-card">${avatar(0)}<h3>${esc(people[0].name)}</h3><span class="founder-tag">${icon('leaf')} ${priorityLabel(people[0])}</span><div class="profile-stats"><div><div class="stat-value">${people[0].elo}</div><div class="stat-label">Twoje punkty ELO</div></div><div><div class="stat-value">#${rank}</div><div class="stat-label">Miejsce w rankingu</div></div></div><button class="text-button" data-page="ranking">Zobacz ranking ekipy ${icon('arrow')}</button></section>`}
const upcoming=()=>`<section class="card next-events"><div class="card-heading"><h2>Zapisz w kalendarzu</h2>${icon('calendar')}</div>${['2026-11-17','2026-11-24','2026-12-01'].map((date,i)=>`<div class="next-event"><div class="date-box"><small>${i===2?'gru':'lis'}</small><strong>${dateObj(date).getDate()}</strong></div><div><div class="event-date">${weekday(date)}, 18:00</div><p>I LO w Gdańsku</p><p class="mini-status">${i===1?'Termin odwołany':'Zapisy otwarte'}</p></div><button data-open-date="${date}" aria-label="Otwórz spotkanie ${longDate(date)}">${icon('right')}</button></div>`).join('')}</section>`;
const community=()=>`<div class="community-note">${icon('people')}<div><h3>Ta sama pasja. Dobra ekipa.</h3><p>Nie możesz przyjść? Odwołaj udział co najmniej 24 godziny przed grą. Ktoś czeka na Twoje miejsce.</p></div></div>`;
function adminPanel(){const e=getEvent();if(e.cancelled)return '';const step=e.step;const eligible=e.roster;return `<section class="card admin-panel"><div class="admin-header"><h2>${icon('shield')} Panel organizatora</h2><button class="button small" data-action="signature">${icon('print')} Lista podpisów</button></div><div class="steps">${['Obecność','Drużyny','Wynik'].map((t,i)=>`<button class="step ${step===i?'active':''}" data-step="${i}" ${i>0&&!e.teams?'disabled':''}>0${i+1} ${t}</button>`).join('')}</div>${step===0?`<p class="page-note" style="margin:0 0 16px">Zaznacz osoby, które są na sali. Tylko one trafią do drużyn.</p><div class="attendance-grid">${eligible.map(id=>`<label class="attendance-row"><input type="checkbox" data-attendance="${id}" ${e.attending.includes(id)?'checked':''}>${esc(people[id].name)}</label>`).join('')}</div><div class="admin-actions"><span>${e.attending.filter(id=>eligible.includes(id)).length} osób na sali</span><div class="rsvp-actions"><button class="button small" data-action="random">${icon('shuffle')} Losowo</button><button class="button primary small" data-action="balanced">Wyrównaj drużyny ${icon('arrow')}</button></div></div>`:step===1?`${e.locked?'<div class="info-box" style="margin-bottom:15px">Składy zatwierdzone. Możesz przejść do wyniku.</div>':'<p class="page-note" style="margin:0 0 15px">Dotknij zawodnika na boisku, aby przenieść go do drugiej drużyny.</p>'}${teamsMarkup()}<div class="admin-actions"><button class="text-button" data-action="random">${icon('shuffle')} Losuj ponownie</button><button class="button primary" data-action="lock-teams">${e.locked?'Wpisz wynik':'Zatwierdź składy'} ${icon('check')}</button></div>`:`<p class="page-note" style="margin-top:0">Wpisz łączną liczbę wygranych setów, bez punktów poszczególnych setów.</p><div class="score-form"><label>Drużyna A<input aria-label="Sety drużyny A" type="number" min="0" max="99" inputmode="numeric" id="score-a" value="${e.scoreDraft[0]}"></label><strong>:</strong><label>Drużyna B<input aria-label="Sety drużyny B" type="number" min="0" max="99" inputmode="numeric" id="score-b" value="${e.scoreDraft[1]}"></label></div>${e.score?`<div class="info-box">Zapisany wynik: <strong>${e.score[0]}:${e.score[1]}</strong>. Ranking w tym mocku pozostaje przykładowy.</div>`:'<div class="info-box">Prototyp zapisuje sam wynik. Algorytm i korekty ELO ustalimy przed implementacją.</div>'}<div class="admin-actions"><button class="text-button" data-step="1">${icon('left')} Składy</button><button class="button primary" data-action="save-score">${e.score?'Zmień wynik':'Zapisz wynik'} ${icon('check')}</button></div>`}</section>`}
function courtMarkup(teams, editable = false) {
  const player = (id, side) => {
    const content = `${avatar(id)}<span class="court-player-name">${esc(people[id].name)}${id === 0 ? '<small>Ty</small>' : ''}</span>${editable ? `<span class="court-transfer" aria-hidden="true">${icon('swap')}</span>` : ''}`;
    return editable
      ? `<button class="court-player" data-move="${id}" aria-label="Przenieś ${esc(people[id].name)} do drużyny ${side ? 'A' : 'B'}" title="Przenieś do drużyny ${side ? 'A' : 'B'}">${content}</button>`
      : `<div class="court-player">${content}</div>`;
  };
  return `<div class="team-court">
    <div class="court-summary">${teams.map((ids, side) => `<div class="court-team-summary side-${side}"><span class="court-team-letter">${side ? 'B' : 'A'}</span><div><h3>Drużyna ${side ? 'B' : 'A'}</h3><p>${ids.length} osób <span>·</span> Średnie ELO <strong>${ids.length ? Math.round(ids.reduce((sum, id) => sum + people[id].elo, 0) / ids.length) : '—'}</strong></p></div></div>`).join('')}</div>
    <div class="court-surface" role="group" aria-label="Schemat boiska z dwiema drużynami">
      <div class="court-lines" aria-hidden="true"></div>
      ${teams.map((ids, side) => `<section class="court-half side-${side}" aria-label="Drużyna ${side ? 'B' : 'A'} na boisku"><span class="court-side-label" aria-hidden="true">DRUŻYNA ${side ? 'B' : 'A'}</span><div class="court-formation">${Array.from({length:6}, (_,slot) => ids[slot] === undefined ? '<div class="court-empty" aria-label="Niewykorzystane miejsce na schemacie"><span>—</span></div>' : player(ids[slot], side)).join('')}</div></section>`).join('')}
      <div class="court-net" aria-hidden="true"><span>SIATKA</span></div>
    </div>
    ${teams.some(ids => ids.length > 6) ? `<div class="court-rotation"><div class="court-rotation-heading">${icon('swap')} Zawodnicy do rotacji <span>Zmiany w ramach swojej drużyny</span></div><div class="court-rotation-teams">${teams.map((ids,side) => `<div class="rotation-side side-${side}"><span class="rotation-label">Drużyna ${side ? 'B' : 'A'}</span>${ids.slice(6).map(id=>player(id,side)).join('') || '<span class="rotation-empty">Wszyscy na boisku</span>'}</div>`).join('')}</div></div>` : ''}
    <p class="court-caption">${icon('ball')} Układ poglądowy — bez przypisanych pozycji i kolejności zagrywki.</p>
  </div>`;
}
function teamsMarkup() {
  const e = getEvent();
  if (!e.teams) return '<p class="empty-state">Drużyny nie zostały jeszcze podzielone.</p>';
  return courtMarkup(e.teams, state.admin && !e.locked);
}
const teamCard=()=>getEvent().locked?`<section class="card card-inner"><div class="card-heading"><h2>Tak dzisiaj gramy</h2>${getEvent().score?`<span class="count-pill">${getEvent().score.join(' : ')}</span>`:'<span class="muted">Składy zatwierdzone</span>'}</div>${teamsMarkup()}</section>`:'';
function meetingA(){return `${pageHead(state.date==='2026-11-10'?'Najbliższe spotkanie':'Szczegóły spotkania','Dobra ekipa, trochę ruchu i dwie godziny dla siebie.')}<div class="dashboard"><div class="main-column"><div class="card">${hero()}${rsvp()}</div>${state.admin?adminPanel():teamCard()}${roster()}<p class="section-footer">${icon('lock')} Historia nieobecności jest widoczna tylko dla Ciebie i administratora.</p></div><aside class="right-column">${personalCard()}${upcoming()}${community()}</aside></div>`}
function meetingB(){return `<div class="focus-intro"><div class="eyebrow muted" style="margin-bottom:12px">TWÓJ COTYGODNIOWY RESET</div><h1>Widzimy się na boisku.</h1><p>Jedno miejsce na zapisy. Więcej czasu na siatkówkę.</p></div><div class="focus-event"><div class="card">${hero()}${rsvp()}</div><div class="focus-tabs"><span class="muted" style="font-size:12px">Twoja ekipa na ${longDate(state.date)}</span><button class="text-button" data-page="calendar">Sprawdź kolejne terminy ${icon('arrow')}</button></div>${state.admin?adminPanel():teamCard()}<div style="margin-top:20px">${roster()}</div><div style="margin-top:20px">${community()}</div></div>`}
function meetingC(){return `<div class="board-intro"><div><div class="eyebrow muted" style="margin-bottom:9px">WIECZÓR Z VOLLEYCREW</div><h1>Jedna ekipa. Jeden plan.</h1><p>Od pierwszej deklaracji do ostatniego seta.</p></div><button class="button" data-page="calendar">${icon('calendar')} Inne terminy</button></div><div class="board-columns"><section><div class="board-label"><span></span>01 · Termin i deklaracja</div><div class="card">${hero()}${rsvp()}</div><div style="margin-top:20px">${community()}</div></section><section><div class="board-label"><span></span>02 · Kto gra</div>${roster()}</section><section><div class="board-label"><span></span>03 · Na sali</div>${state.admin?adminPanel():getEvent().locked?teamCard():`<div class="card card-inner"><h2>Czas na dobrą grę</h2><p class="page-note">Tutaj pojawią się zatwierdzone drużyny i wynik spotkania.</p><button class="button" data-action="role" style="margin-top:18px">${icon('shield')} Sprawdź widok organizatora</button></div>`}</section></div>`}
function calendar(){const start=new Date(state.year,state.month,1);const offset=(start.getDay()+6)%7;const num=new Date(state.year,state.month+1,0).getDate();const monthEvents=[];const days=Array.from({length:offset},()=>'<span></span>');for(let d=1;d<=num;d++){const date=`${state.year}-${String(state.month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const isEvent=new Date(state.year,state.month,d).getDay()===2&&date>='2026-11-05';if(isEvent)monthEvents.push(date);days.push(isEvent?`<button class="day event ${date===state.date?'selected':''} ${date==='2026-11-24'?'cancelled':''}" data-select-date="${date}" aria-label="${longDate(date)}${date==='2026-11-24'?', odwołane':''}" aria-pressed="${date===state.date}">${d}</button>`:`<span class="day">${d}</span>`)}return `${pageHead('Kalendarz','Zarezerwuj sobie czas na grę. Zapisz się także na dalsze terminy.')}<div class="calendar-layout"><section class="card card-inner"><div class="calendar-toolbar"><h2 style="text-transform:capitalize">${start.toLocaleDateString('pl-PL',{month:'long',year:'numeric'})}</h2><div style="display:flex;gap:7px"><button class="arrow-button" data-month="-1" aria-label="Poprzedni miesiąc">${icon('left')}</button><button class="arrow-button" data-month="1" aria-label="Następny miesiąc">${icon('right')}</button></div></div><div class="calendar-grid">${['Pon','Wt','Śr','Czw','Pt','Sob','Nd'].map(x=>`<span class="weekday">${x}</span>`).join('')}${days.join('')}</div><p class="page-note">Zielone dni — spotkania · przekreślona data — odwołane.<br>Wybierz datę, żeby zobaczyć szczegóły.</p></section><section>${monthEvents.includes(state.date)?calendarEvent(state.date):monthEvents.map(calendarEvent).join('')||'<div class="card empty-state">Brak przyszłych spotkań w tym miesiącu.</div>'}<p class="page-note">W mocku pokazujemy obecny harmonogram wtorkowy. Zmianę harmonogramu zaprojektujemy osobno.</p></section></div>`}
function calendarEvent(date){const e=events.get(date)||initialEvent(date);return `<div class="card event-card"><span class="tag">${e.cancelled?'ODWOŁANE':e.mine==='confirmed'?'MASZ MIEJSCE':e.mine==='wait'?'JESTEŚ NA REZERWIE':'ZAPISY OTWARTE'}</span><h3>${longDate(date)}</h3><p>${weekday(date)}, 18:00–20:00<br>I LO w Gdańsku · ${e.cancelled?'Brak gry w tym terminie':`${e.roster.length}/14 miejsc zajętych`}</p><button class="button ${e.cancelled?'':'primary'}" data-open-date="${date}">Szczegóły spotkania ${icon('arrow')}</button></div>`}
function ranking(){const sorted=[...people].sort((a,b)=>b.elo-a.elo);return `${pageHead('Gramy dla przyjemności.','A odrobina rywalizacji dodaje smaku. Oto ranking naszej ekipy.')}<div style="margin-bottom:23px" class="segmented"><button data-rank-tab="players" class="${state.rankingTab==='players'?'active':''}">Ranking zawodników</button><button data-rank-tab="history" class="${state.rankingTab==='history'?'active':''}">Wyniki spotkań</button></div><div class="rank-layout"><section class="card">${state.rankingTab==='players'?`<div class="card-inner"><h2>Ranking ekipy <span class="count-pill">${people.length}</span></h2></div><table class="ranking-table"><thead><tr><th scope="col">#</th><th scope="col">Zawodnik</th><th scope="col" style="text-align:right">Punkty ELO</th></tr></thead><tbody>${sorted.map((p,i)=>`<tr class="${p.id===0?'own':''}"><td>${String(i+1).padStart(2,'0')}</td><td><div class="person">${avatar(p.id)}<div><div class="person-name">${esc(p.name)}${p.id===0?' <span class="you">Ty</span>':''}</div>${state.admin?`<div class="founder">${priorityLabel(p)}</div>`:''}</div></div></td><td>${p.elo}</td></tr>`).join('')}</tbody></table>`:`<div class="card-inner"><h2>Ostatnie spotkania</h2></div>${[['3 listopada 2026','5 : 3','Zwycięstwo drużyny A'],['27 października 2026','3 : 3','Remis'],['20 października 2026','2 : 4','Zwycięstwo drużyny B']].map(([d,s,t])=>`<div class="history-match"><div class="eyebrow muted">${d}</div><div class="match-score">${s}</div><p>${t} · I LO w Gdańsku</p><button class="text-button" data-action="match-details">Zobacz składy ${icon('right')}</button></div>`).join('')}`}</section><aside class="right-column">${personalCard()}<section class="card card-inner"><h2>Jak to działa?</h2><p class="page-note">Każdy zaczyna od 1000 punktów. Liczy się siła obu drużyn i proporcja wygranych setów.</p><p class="page-note">Większa przewaga w setach oznacza większą zmianę przy tych samych składach. Ranking aktualizujemy raz po spotkaniu.</p><div class="info-box" style="margin-top:18px">Punkty i wyniki są fikcyjne. Dokładna skala ELO pozostaje do ustalenia.</div></section></aside></div>`}
function profile(){return `${pageHead('Mój profil','Twoje dane, ustawienia i historia wspólnych wtorków.')}<div class="profile-layout"><section class="card card-inner"><div class="person" style="margin-bottom:25px">${avatar(0)}<div><h2>${esc(people[0].name)}</h2><p class="person-sub">${priorityLabel(people[0])} · ${people[0].elo} ELO</p></div></div><form id="profile-form"><label class="field">Imię i nazwisko<input name="fullName" value="${esc(people[0].name)}" autocomplete="name" required maxlength="80"></label><label class="field">Przydomek (opcjonalnie)<input name="nickname" value="${esc(people[0].nickname)}" autocomplete="nickname" maxlength="40"><small class="muted">Pomaga odróżnić osoby o tym samym imieniu i nazwisku. Nie trafi na listę dla szkoły.</small></label><button class="button primary" type="submit">Zapisz dane ${icon('check')}</button></form><div style="border-top:1px solid var(--line);margin-top:28px;padding-top:24px"><h3>Twój PIN</h3><p class="page-note">Sześć cyfr do logowania na innym urządzeniu.</p><button class="button" style="margin-top:14px" data-action="pin">${icon('lock')} Zmień PIN</button></div><p class="page-note">Zmiany w prototypie działają tylko do odświeżenia strony. Nie używaj prawdziwego PIN-u.</p></section><section class="card card-inner"><div class="card-heading"><h2>Historia obecności</h2>${icon('lock')}</div><div class="info-box">Ta historia jest prywatna. Widzisz ją Ty i administrator.</div>${[['3 listopada 2026','Obecność',''],['27 października 2026','Zwykła rezygnacja',''],['20 października 2026','Późna rezygnacja','late'],['13 października 2026','Obecność',''],['6 października 2026','Bez odwołania','absent']].map(([d,t,c])=>`<div class="history-row"><span>${d}</span><span class="history-label ${c}">${t}</span></div>`).join('')}<p class="page-note">Przykładowa historia. Późna rezygnacja oznacza zgłoszenie mniej niż 24 godziny przed grą. Nie stosujemy automatycznych kar.</p></section></div>`}
function render(){document.body.className=`variant-${state.variant.toLowerCase()}`;const content=state.page==='meeting'?({A:meetingA,B:meetingB,C:meetingC})[state.variant]():({calendar,ranking,profile})[state.page]();const note='<p class="footer-caption">VOLLEYCREW · PROTOTYP DO ROZMOWY · Fikcyjne dane, zmiany nie są zapisywane na stałe.</p>';document.getElementById('app').innerHTML=state.variant==='A'?`<div class="shell">${sidebar()}<div class="workspace">${topbar()}<main class="content" id="main">${content}${note}</main></div></div>${mobileNav()}`:`<header class="alt-header">${brand()}${nav()}${topActions()}</header><main class="content" id="main">${content}${note}</main>${mobileNav()}`;renderSwitcher()}
function renderSwitcher(){document.getElementById('prototype-switcher').innerHTML=`<button data-variant-dir="-1" aria-label="Poprzedni wariant">${icon('left')}</button><span><small>Prototyp · wybierz układ</small>${({A:'A · Pulpit ekipy',B:'B · Skupienie na spotkaniu',C:'C · Tablica spotkania'})[state.variant]}</span><button data-variant-dir="1" aria-label="Następny wariant">${icon('right')}</button><button data-action="scenarios" aria-label="Przykładowe sytuacje" title="Sprawdź różne sytuacje">${icon('shuffle')}</button>`}
function switchVariant(dir){if(focusedPrototype)return;const keys=['A','B','C'];state.variant=keys[(keys.indexOf(state.variant)+dir+3)%3];const url=new URL(location.href);url.searchParams.set('variant',state.variant);history.replaceState({},'',url);render();announce(`Układ ${state.variant}. Ten sam stan spotkania.`)}
let toastTimer;function announce(message){const toast=document.getElementById('toast');toast.textContent=message;toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),3600)}
let previousFocus;function modal(title,body,actions=''){previousFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="Zamknij">${icon('close')}</button><h2 id="modal-title">${title}</h2>${body}<div class="modal-actions">${actions||'<button class="button primary" data-action="close-modal">Rozumiem</button>'}</div></section></div>`;document.querySelector('.modal button').focus()}
function closeModal(){document.getElementById('modal-root').innerHTML='';previousFocus?.isConnected&&previousFocus.focus()}
function splitTeams(balanced){const e=getEvent();if(e.locked||e.score){modal('Zmienić zatwierdzone składy?','<p>W prototypie możesz wrócić do podziału. Zapisany wynik zostanie wyczyszczony. Zasady korekt prawdziwego rankingu ustalimy osobno.</p>',`<button class="button" data-action="close-modal">Wróć</button><button class="button primary" data-action="reset-teams" data-balanced="${balanced}">Zmień składy</button>`);return}const ids=e.attending.filter(id=>e.roster.includes(id));if(ids.length<2){announce('Zaznacz co najmniej dwie obecne osoby.');return}if(balanced){ids.sort((a,b)=>people[b].elo-people[a].elo);const teams=[[],[]];ids.forEach((id,i)=>teams[[0,1,1,0][i%4]].push(id));e.teams=teams}else{for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}e.teams=[ids.filter((_,i)=>i%2===0),ids.filter((_,i)=>i%2===1)]}e.locked=false;e.step=1;render();announce(balanced?'Podział według ELO. Możesz ręcznie zmienić składy.':'Nowe losowe składy są gotowe.')}
const actions={
  role(){state.admin=!state.admin;render();announce(state.admin?'Przykładowy widok organizatora':'Przykładowy widok zawodnika')},
  'close-modal':closeModal,
  scenarios(){modal('Sprawdź różne sytuacje','<p>Przykładowe stany najbliższego spotkania. Wybranie scenariusza resetuje jego dane.</p><div style="display:grid;gap:9px;margin-top:20px">'+[['full','Komplet i rezerwa'],['open','Są wolne miejsca'],['offer','Propozycja miejsca z rezerwy'],['changed','Termin zmieniony'],['cancelled','Spotkanie odwołane']].map(([key,text])=>`<button class="button" data-scenario="${key}">${text} ${icon('arrow')}</button>`).join('')+'</div>')},
  'signup-info'(){modal('Jak działają zapisy?','<p>Mamy 14 miejsc. Wcześniej niż 24 godziny przed grą kolejność pierwszeństwa to: założyciel, zawodnik, gość. W obrębie statusu liczy się kolejność zgłoszeń. Nowy profil otrzymuje status gościa; statusy innych osób nie są widoczne zawodnikom.</p><p style="margin-top:12px">W ostatnich 24 godzinach zajęte miejsca są chronione. Miejsce z rezerwy wymaga przyjęcia propozycji — organizator kontaktuje się na Messengerze.</p>')},
  join(){const e=getEvent();e.changed=false;if(e.roster.includes(0)){e.mine='confirmed'}else if(e.roster.length<14){e.roster.push(0);e.wait=e.wait.filter(id=>id!==0);e.mine='confirmed'}else{if(!e.wait.includes(0))e.wait.push(0);e.mine='wait'}render();announce(e.mine==='confirmed'?'Udział potwierdzony. Masz miejsce!':'Zgłoszenie dodane do rezerwy. Kolejność w mocku jest poglądowa.')},
  absent(){const e=getEvent();e.changed=false;e.mine='absent';render();announce('Deklaracja „Nie będę” zapisana w prototypie.')},
  withdraw(){const e=getEvent();modal('Zmieniły się plany?',`<p>${e.mine==='wait'?'Wycofasz swoje zgłoszenie z listy rezerwowej.':`Zrezygnujesz z miejsca na ${longDate(e.date)}. W tym scenariuszu do gry pozostało więcej niż 24 godziny — będzie to zwykła rezygnacja.`}</p>`,`<button class="button" data-action="close-modal">Zostaję</button><button class="button danger" data-action="confirm-withdraw">${e.mine==='wait'?'Wycofuję zgłoszenie':'Rezygnuję z gry'}</button>`)},
  'confirm-withdraw'(){const e=getEvent();e.roster=e.roster.filter(id=>id!==0);e.wait=e.wait.filter(id=>id!==0);e.attending=e.attending.filter(id=>id!==0);e.mine='absent';e.teams=null;e.locked=false;e.score=null;e.step=0;closeModal();render();announce('Rezygnacja zapisana. Rezerwa wymaga osobnego potwierdzenia.')},
  'accept-offer'(){const e=getEvent();if(e.roster.length>=14){announce('Nie ma już wolnego miejsca.');return}e.offer=false;e.mine='confirmed';e.roster.push(0);e.wait=e.wait.filter(id=>id!==0);render();announce('Miejsce z rezerwy przyjęte. Widzimy się na boisku!')},
  'decline-offer'(){const e=getEvent();e.offer=false;e.mine='absent';e.wait=e.wait.filter(id=>id!==0);render();announce('Propozycja odrzucona. Organizator może zaprosić kolejną osobę.')},
  random(){splitTeams(false)},balanced(){splitTeams(true)},
  'reset-teams'(button){const e=getEvent();e.locked=false;e.score=null;closeModal();splitTeams(button.dataset.balanced==='true')},
  'lock-teams'(){const e=getEvent();if(!e.teams?.every(t=>t.length>0&&t.length<=7)){announce('Każda drużyna musi liczyć od 1 do 7 osób.');return}if(e.locked){e.step=2;render();return}e.locked=true;render();announce('Składy zatwierdzone. Po grze przejdź do wyniku.')},
  'save-score'(){const e=getEvent();if(!e.locked){announce('Najpierw zatwierdź składy drużyn.');e.step=1;render();return}const a=document.getElementById('score-a').value,b=document.getElementById('score-b').value;const score=[Number(a),Number(b)];if(a===''||b===''||!score.every(v=>Number.isInteger(v)&&v>=0&&v<=99)){announce('Wpisz całkowitą liczbę setów od 0 do 99.');return}if(score[0]+score[1]===0){modal('Nie rozegrano setów','<p>0:0 nie jest rozstrzygniętym spotkaniem. Zasada jego zamykania pozostaje do ustalenia; w mocku nie zapisujemy wyniku ani nie zmieniamy rankingu.</p>');return}e.scoreDraft=score;modal('Zapisać wynik?',`<p>Drużyna A <strong>${score[0]} : ${score[1]}</strong> Drużyna B</p><p style="margin-top:12px">Wynik zapisze się tylko w tej sesji prototypu. Punkty ELO pozostaną przykładowe.</p>`,'<button class="button" data-action="close-modal">Popraw</button><button class="button primary" data-action="confirm-score">Zapisz wynik</button>')},
  'confirm-score'(){const e=getEvent();e.score=[...e.scoreDraft];closeModal();render();announce(`Wynik ${e.score.join(':')} zapisany w prototypie.`)},
  signature(){const e=getEvent();modal('Podgląd listy podpisów',`<p>Propozycja wydruku z potwierdzonej listy zapisów. Format i moment generowania pozostają do zatwierdzenia.</p><div class="signature-preview"><h1>Lista uczestników</h1><p>I LO w Gdańsku</p><p>${longDate(e.date)} ${dateObj(e.date).getFullYear()} · 18:00–20:00</p><table><thead><tr><th>Lp.</th><th>Imię i nazwisko</th><th>Podpis</th></tr></thead><tbody>${e.roster.map((id,i)=>`<tr><td>${i+1}</td><td>${esc(people[id].name)}</td><td></td></tr>`).join('')}</tbody></table></div>`,'<button class="button" data-action="close-modal">Zamknij</button><button class="button primary" data-action="print">Drukuj / zapisz jako PDF</button>')},
  print(){window.print()},
  pin(){modal('Zmiana PIN-u','<p>To demonstracja formularza. Nie podawaj prawdziwego PIN-u.</p><form id="pin-form"><label class="field">Obecny PIN<input type="password" name="oldPin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" minlength="6" required autocomplete="off"></label><label class="field">Nowy PIN · 6 cyfr<input type="password" name="newPin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" minlength="6" required autocomplete="off"></label><label class="field">Powtórz nowy PIN<input type="password" name="repeatPin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" minlength="6" required autocomplete="off"></label><button class="button primary" type="submit">Zatwierdź przykładowo</button></form>','<button class="button" data-action="close-modal">Anuluj</button>')},
  'match-details'(){modal('Przykładowe składy','<p>Podgląd historycznego spotkania. Dane i ranking są fikcyjne.</p><div style="margin-top:18px">'+courtMarkup([[0,2,4,6,8,10],[1,3,5,7,9,11]])+'</div>')},
};
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.page){state.page=b.dataset.page;if(state.page==='meeting')state.date='2026-11-10';render();window.scrollTo(0,0)}else if(b.dataset.action){actions[b.dataset.action]?.(b)}else if(b.dataset.variantDir){switchVariant(Number(b.dataset.variantDir))}else if(b.dataset.openDate){state.date=b.dataset.openDate;state.page='meeting';render();window.scrollTo(0,0)}else if(b.dataset.selectDate){state.date=b.dataset.selectDate;render()}else if(b.dataset.month){state.month+=Number(b.dataset.month);if(state.month<0){state.month=11;state.year--}if(state.month>11){state.month=0;state.year++}render()}else if(b.dataset.rankTab){state.rankingTab=b.dataset.rankTab;render()}else if(b.dataset.step){getEvent().step=Number(b.dataset.step);render()}else if(b.dataset.move){const e=getEvent(),id=Number(b.dataset.move);if(e.locked)return;const from=e.teams.findIndex(t=>t.includes(id));if(e.teams[1-from].length>=7){announce('W jednej drużynie może być maksymalnie 7 osób.');return}e.teams[from]=e.teams[from].filter(p=>p!==id);e.teams[1-from].push(id);render()}else if(b.dataset.scenario){state.date='2026-11-10';state.page='meeting';const e=initialEvent(state.date);if(b.dataset.scenario==='open'){e.roster=e.roster.filter(id=>id<12&&id!==0);e.wait=[];e.mine='none'}if(b.dataset.scenario==='offer'){e.roster=e.roster.filter(id=>id!==0);e.wait=[0,14,15];e.mine='wait';e.offer=true}if(b.dataset.scenario==='changed'){e.date='2026-11-12';e.changed=true;e.mine='none';e.roster=e.roster.filter(id=>id!==0);e.wait=[]}if(b.dataset.scenario==='cancelled')e.cancelled=true;events.set(state.date,e);closeModal();render();announce('Wybrany przykładowy stan spotkania.')} });
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.attendance!==undefined){const e=getEvent(),id=Number(el.dataset.attendance);if(e.locked){el.checked=e.attending.includes(id);announce('Najpierw wróć do podziału i zmień zatwierdzone składy.');return}e.attending=e.attending.filter(p=>p!==id);if(el.checked)e.attending.push(id);e.teams=null;e.score=null;render()}});
document.addEventListener('input',event=>{if(event.target.id==='score-a'||event.target.id==='score-b'){getEvent().scoreDraft[event.target.id==='score-a'?0:1]=event.target.value}});
document.addEventListener('submit',event=>{if(event.target.id==='profile-form'){event.preventDefault();const value=new FormData(event.target).get('fullName').trim();if(value.split(/\s+/).length<2){announce('Podaj imię i nazwisko do listy podpisów.');return}people[0].name=value;people[0].nickname=String(new FormData(event.target).get('nickname')||'').trim();render();announce('Dane zmienione tylko w tej sesji prototypu.')}if(event.target.id==='pin-form'){event.preventDefault();const data=new FormData(event.target);if(data.get('newPin')!==data.get('repeatPin')){announce('Nowy PIN i jego powtórzenie muszą być takie same.');return}closeModal();announce('Formularz poprawny. Mock nie zapisuje ani nie weryfikuje PIN-u.')}});
document.addEventListener('keydown',event=>{const modalEl=document.querySelector('.modal');if(modalEl){if(event.key==='Escape')closeModal();if(event.key==='Tab'){const focusables=[...modalEl.querySelectorAll('button,input,a[href]')].filter(e=>!e.disabled);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}return}if(['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)||event.target.isContentEditable)return;if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();switchVariant(event.key==='ArrowLeft'?-1:1)}});
render();
